  { courseId: 11, title: 'JavaScript 기초', teacher: '민수', closed: false },
  { courseId: 12, title: 'React 시작', teacher: '지수', closed: true },
];

function CourseItem({ course }) {
  return <li>{course.title}: {course.closed ? '신청 마감' : course.teacher}</li>;
}
function App() {
  return <ul>{courses.map((course) => <CourseItem key={course.courseId} course={course} />)}</ul>;
}
ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

