const products = [
  { id: 1, name: '셔츠', price: 30000, stock: 2 },
  { id: 2, name: '모자', price: 15000, stock: 0 },
];

function ProductItem({ product }) {
  return <li>{product.name}: {product.stock === 0 ? '품절' : `${product.price}원`}</li>;
}
function App() {
  return <ul>{products.map((product) => <ProductItem key={product.id} product={product} />)}</ul>;
}
ReactDOM.createRoot(document.querySelector('#root')).render(<App />);
